using Finora.Application;using Finora.Domain;namespace Finora.App;public partial class App:Microsoft.Maui.Controls.Application{private readonly IFinanceStore _store;private readonly IAppSettingsService _settings;private readonly IAppLockService _appLock;private DateTimeOffset? _deactivated;public App(IFinanceStore store,IAppSettingsService settings,IAppLockService appLock){InitializeComponent();_store=store;_settings=settings;_appLock=appLock;UserAppTheme=settings.Theme switch{ThemePreference.Light=>AppTheme.Light,ThemePreference.Dark=>AppTheme.Dark,_=>AppTheme.Unspecified};}protected override Window CreateWindow(IActivationState? activationState){var shell=new AppShell();var window=new Window(shell);window.Deactivated+=(_,_)=>_deactivated=DateTimeOffset.UtcNow;window.Activated+=async(_,_)=>await LockAsync();_=InitAsync();return window;}private async Task InitAsync(){await _store.InitializeAsync();await MainThread.InvokeOnMainThreadAsync(async()=>{if(await _appLock.HasPinAsync())await Shell.Current.GoToAsync("//lock");else if(!_settings.OnboardingComplete)await Shell.Current.GoToAsync("//onboarding");else await Shell.Current.GoToAsync("//dashboard");});}private async Task LockAsync(){if(_deactivated is null)return;var elapsed=DateTimeOffset.UtcNow-_deactivated.Value;_deactivated=null;if(elapsed>=TimeSpan.FromMinutes(_settings.AutoLockMinutes)&&await _appLock.HasPinAsync()&&Shell.Current is not null)await Shell.Current.GoToAsync("//lock");}}
